def clean(s):
    s = s.replace(' ', '_')
    assert '|' not in s and '\n' not in s, s[:80]
    s.encode('ascii')
    return s


def main():
    names = [c[0] for c in CHECKS] + [s[0] for s in STEPS]
    assert len(CHECKS) == 7 and len(STEPS) == 62
    step_names = [s[0] for s in STEPS]
    assert sorted(step_names) == sorted(PER_STEP_ORDER) and len(set(step_names)) == 62
    by = dict((s[0], s) for s in STEPS)
    rows = []
    for (t, st, ln, rs) in CHECKS + [by[n] for n in PER_STEP_ORDER]:
        rows.append('YM4_04C_G_ATTACK_STATUS|target=' + t + '|status=' + st + '|seat=' + SEAT + '|commit=' + COMMIT
                    + '|lines=' + clean(ln) + '|reason=' + clean(rs) + '|json=0')
    cnt = {}
    for (t, st, ln, rs) in CHECKS:
        cnt[('c', st)] = cnt.get(('c', st), 0) + 1
    for (t, st, ln, rs) in STEPS:
        cnt[('s', st)] = cnt.get(('s', st), 0) + 1
